import * as T from './vendor/three.module.js';
import {makeDish} from './dish-models.js';
import {recipes} from './recipe-catalog.js';
export function createKitchenMotion({host,avatar,body,arms,legs,indoor,fridge,camera,route,layout}){
 const bubble=document.createElement('div');bubble.className='kitchen-bubble';bubble.hidden=true;host.parentElement.append(bubble);
 const hat=new T.Group();body.add(hat);hat.position.y=1.04;const material=new T.MeshStandardMaterial({color:0xfff8e8,roughness:.85});function piece(geo,x,y,z){const m=new T.Mesh(geo,material);m.position.set(x,y,z);hat.add(m)}piece(new T.CylinderGeometry(.19,.19,.08,24),0,.035,0);piece(new T.CylinderGeometry(.18,.19,.16,24),0,.14,0);for(let i=0;i<5;i++){const a=i*Math.PI*2/5;piece(new T.SphereGeometry(.085,16,12),Math.cos(a)*.10,.23,Math.sin(a)*.10)}hat.visible=false;
 const spoon=new T.Mesh(new T.CylinderGeometry(.015,.022,.34,12),new T.MeshStandardMaterial({color:0xa78250}));arms[1].add(spoon);spoon.position.set(0,-.40,.015);spoon.visible=false;
 const fridgeBody=fridge.children[0],interior=new T.Group();const innerMat=new T.MeshStandardMaterial({color:0xe1eadb,roughness:.65});function panel(x,y,z,w,h,d){const m=new T.Mesh(new T.BoxGeometry(w,h,d),innerMat);m.position.set(x,y,z);interior.add(m)}panel(0,.79,-.30,.70,1.55,.04);for(const x of [-.34,.34])panel(x,.79,0,.03,1.55,.62);for(const y of [.04,.48,.92,1.56])panel(0,y,0,.68,.028,.62);interior.visible=false;
 const door=new T.Group();fridge.add(door);door.position.set(-.36,0,.34);indoor.updateWorldMatrix(true,true);for(const child of [...fridge.children].slice(1,-1))door.attach(child);fridge.add(interior);
 let phase='idle',elapsed=0,recipe=null,choices=[],callbacks=null,dish=null,busy=false,path=[],from=null,leg=0,rollIndex=-1,walkTime=0;
 const point=new T.Vector3();const stool=new T.Mesh(new T.BoxGeometry(.50,.30,.43),new T.MeshStandardMaterial({color:0xc4ac7e,roughness:.85}));stool.position.set(.8,.15,-.84);stool.visible=false;indoor.add(stool);
 function disposeDish(){if(!dish)return;dish.removeFromParent();dish.traverse(o=>{o.geometry?.dispose();for(const m of o.material?[].concat(o.material):[])m.dispose()});dish=null}
 function setPhase(p){phase=p;elapsed=0}
 function showDish(){disposeDish();dish=makeDish(recipe);const b=new T.Box3().setFromObject(dish),size=b.getSize(new T.Vector3());dish.scale.setScalar(Math.min(.55/size.x,.40/size.z,1));body.add(dish);dish.position.set(0,.50,.38)}
 function finish(){setPhase('idle');hat.visible=spoon.visible=false;bubble.hidden=true;door.rotation.y=0;stool.visible=false;fridgeBody.visible=true;interior.visible=false;avatar.position.y=.022;disposeDish();arms.forEach(a=>a.rotation.set(0,0,0));callbacks?.done?.()}
 async function choose(destination){if(busy||phase!=='ready')return;busy=true;bubble.querySelectorAll('button').forEach(b=>b.disabled=true);try{bubble.hidden=true;hat.visible=false;avatar.position.y=.022;stool.visible=false;setPhase(destination==='serve'?'carry-table':'carry-fridge');path=route(...(destination==='serve'?layout().lower.stops.table:layout().lower.stops.fridge));if(!path.length){finish();return}path=path.filter((p,i,a)=>i===0||i===a.length-1||Math.abs((p.x-a[i-1].x)*(a[i+1].z-p.z)-(p.z-a[i-1].z)*(a[i+1].x-p.x))>1e-6);walkTime=0;from=avatar.position.clone();leg=0;}finally{busy=false}}
 function ready(){setPhase('ready');avatar.position.y=.022;stool.visible=false;hat.visible=spoon.visible=false;showDish();avatar.rotation.y=.25;arms.forEach((a,i)=>a.rotation.set(-1.15,0,i?-.15:.15));bubble.innerHTML='<strong>'+recipes[recipe].name+'</strong><div><button data-kitchen-serve>端上桌</button><button data-kitchen-store>放冰箱</button></div>';bubble.querySelector('[data-kitchen-serve]').onclick=()=>choose('serve');bubble.querySelector('[data-kitchen-store]').onclick=()=>choose('store')}
 function roll(){const pool=choices.length>1?choices.filter(id=>id!==recipe):choices;recipe=pool[Math.floor(Math.random()*pool.length)];rollIndex=-1;hat.visible=spoon.visible=false;setPhase('roll');bubble.hidden=false;bubble.innerHTML='<span>吃点什么呢？</span><strong class="kitchen-roll"></strong>'}
 function confirmRecipe(){setPhase('choice');bubble.innerHTML='<strong>'+recipes[recipe].name+'</strong><div><button data-kitchen-cook>做饭</button><button data-kitchen-reroll>重选</button><button data-kitchen-cancel aria-label="取消做饭">×</button></div>';bubble.querySelector('[data-kitchen-cook]').onclick=()=>{if(phase!=='choice')return;setPhase('cook');hat.visible=spoon.visible=true;bubble.innerHTML='<strong>'+recipes[recipe].name+'</strong>'};bubble.querySelector('[data-kitchen-reroll]').onclick=()=>{if(phase==='choice')roll()};bubble.querySelector('[data-kitchen-cancel]').onclick=finish}
 return {get active(){return phase!=='idle'},start(list,cb){if(phase!=='idle')return false;if(!list.length)return false;choices=list;callbacks=cb;recipe=null;avatar.rotation.y=layout().cookYaw;avatar.position.y=.322;stool.position.set(avatar.position.x,.15,avatar.position.z);stool.visible=true;roll();return true},tick(dt){if(phase==='idle')return;elapsed+=dt;const t=elapsed;point.set(0,1.65,0);avatar.localToWorld(point);point.project(camera);bubble.style.left=Math.max(115,Math.min(host.clientWidth-115,(point.x*.5+.5)*host.clientWidth))+'px';bubble.style.top=Math.max(110,Math.min(host.clientHeight-220,(-point.y*.5+.5)*host.clientHeight))+'px';
 if(phase==='roll'){const index=Math.floor(t/(t<.65?.08:.16));if(index!==rollIndex){rollIndex=index;const label=bubble.querySelector('strong');label.textContent=recipes[choices[index%choices.length]].name;label.animate([{transform:'translateY(5px)',opacity:.3},{transform:'translateY(0)',opacity:1}],{duration:110})}if(t>1.1)confirmRecipe()}
 else if(phase==='cook'){avatar.rotation.y=Math.PI;arms[0].rotation.set(-1.7+Math.sin(t*10)*.12,0,.12);arms[1].rotation.set(-1.8+Math.sin(t*5)*.10,0,Math.cos(t*5)*.12);body.rotation.z=Math.sin(t*3)*.025;if(t>1.9){body.rotation.z=0;setPhase('saving');callbacks.cooked(recipe).then(ok=>{if(ok)ready();else{finish()}}).catch(()=>finish())}}
 else if(phase.startsWith('carry-')){walkTime+=dt;arms.forEach((a,i)=>a.rotation.set(-1.12,0,i?-.13:.13));const target=path[leg],duration=Math.max(.02,from.distanceTo(target)/.8),u=Math.min(1,t/duration);avatar.position.lerpVectors(from,target,u);const yaw=Math.atan2(target.x-from.x,target.z-from.z);avatar.rotation.y+=Math.atan2(Math.sin(yaw-avatar.rotation.y),Math.cos(yaw-avatar.rotation.y))*Math.min(1,dt*12);legs.forEach((a,i)=>a.rotation.x=Math.sin(walkTime*9+i*Math.PI)*.24);if(u===1){leg++;from=avatar.position.clone();elapsed=0;if(leg===path.length){legs.forEach(a=>a.rotation.x=0);if(phase==='carry-table'){avatar.rotation.y=Math.PI;setPhase('placing-save');callbacks.serve().then(ok=>{if(ok){disposeDish();setPhase('place')}else ready()}).catch(()=>ready())}else{avatar.rotation.y=Math.atan2(fridge.position.x-avatar.position.x,fridge.position.z-avatar.position.z);fridgeBody.visible=false;interior.visible=true;setPhase('store')}}}}
 else if(phase==='place'){arms.forEach(a=>a.rotation.x=-1.12*(1-Math.min(1,t/.45)));if(t>.5)finish()}
 else if(phase==='store'){door.rotation.y=-Math.sin(Math.min(1,t/2.2)*Math.PI)*1.1;if(dish){dish.position.z=.38+Math.min(t,1)*.27;dish.scale.multiplyScalar(t>1?.92:1)}if(t>2.3)finish()}
 },state(){return {phase,recipe,chefHat:hat.visible}},dispose(){finish();bubble.remove();hat.traverse(o=>o.geometry?.dispose());hat.removeFromParent();material.dispose();spoon.geometry.dispose();spoon.material.dispose();spoon.removeFromParent();stool.geometry.dispose();stool.material.dispose();stool.removeFromParent();interior.traverse(o=>o.geometry?.dispose());innerMat.dispose();interior.removeFromParent()}};
}
